    [MenuItem("Tools/Engineering Building/Building Generator")]
    static void Open(){var window=GetWindow<EngineeringFloor1Generator>("Building 9 v6.13.1");window.minSize=new Vector2(320,240);}
    void OnEnable()
    {
        EditorApplication.playModeStateChanged-=OnPlayModeStateChanged;
        EditorApplication.playModeStateChanged+=OnPlayModeStateChanged;
        uiLayoutWidth=0;uiPadding=null;uiButton=null;uiCardTitle=null;
        if(uiSettingsVersion<1)
        {
            showFloors=true;showRoofs=true;showSceneOptions=true;showSettings=false;showStructure=true;
            showWindows=false;showRoofSettings=false;showOutdoorSettings=false;showHelp=false;showStatus=false;scroll=Vector2.zero;uiSettingsVersion=1;
        }
        runtimePlans=null;
        meshBuildFolder=null;windowProbes.Clear();
        working=false;queuedOperation=0;lastBuildError="";buildStage="Ready";referenceMaterials.Clear();
        // Recover newly added settings if an older saved window restores zeros.
        if(towerWindowSill<=0||towerWindowHeight<=0){towerWindowSill=2.35f;towerWindowHeight=1.10f;}
        if(wingWindowSill<=0||wingWindowHeight<=0){wingWindowSill=.95f;wingWindowHeight=2.05f;}
        if(roofSettingsVersion<1)
        {roofSlabDepth=.22f;roofParapetHeight=.60f;penthouseServiceRise=.60f;roofsVisible=true;roofSettingsVersion=1;}
        if(southEntranceSettingsVersion<2)
        {includePicnicSeating=true;picnicTableCount=2;southEntranceSettingsVersion=2;}
        status="Ready. Generate six floors and roofs, or inspect the building already in the scene.";
        titleContent=new GUIContent("Building 9 v6.13.1");
        minSize=new Vector2(320,240);
        try {buildStage="loading embedded plans";Data(true);buildStage="Ready";}
        catch(ExitGUIException){throw;}
        catch(Exception error){ReportFailure(error);}
    }
    void OnDisable()
    {
        EditorApplication.delayCall-=RunQueuedOperation;
        EditorApplication.playModeStateChanged-=OnPlayModeStateChanged;
        queuedOperation=0;working=false;
    }
    static bool IsPlaySession
    {get{return EditorApplication.isPlaying||EditorApplication.isPlayingOrWillChangePlaymode;}}
    void OnPlayModeStateChanged(PlayModeStateChange state)
    {
        if(state==PlayModeStateChange.ExitingEditMode||state==PlayModeStateChange.EnteredPlayMode)
        {EditorApplication.delayCall-=RunQueuedOperation;queuedOperation=0;}
        Repaint();
    }
    static void RecordSceneChange(UnityEngine.Object target,string action)
    {if(target!=null&&!IsPlaySession)Undo.RecordObject(target,action);}
    void OnGUI()
    {
        // Keep breakpoints fixed for the entire IMGUI layout/repaint cycle.
        // Actual rectangles still stretch to the live width of the window.
        if(Event.current.type==EventType.Layout||uiLayoutWidth<=0)
            uiLayoutWidth=Mathf.Max(1f,position.width-34f);
        if(uiPadding==null)uiPadding=new GUIStyle{padding=new RectOffset(8,8,6,6)};
        if(uiButton==null)uiButton=new GUIStyle(GUI.skin.button){wordWrap=true};
        if(uiCardTitle==null)uiCardTitle=new GUIStyle(EditorStyles.boldLabel){wordWrap=true};
        using(new EditorGUILayout.VerticalScope(uiPadding,GUILayout.MinWidth(0f),GUILayout.ExpandHeight(true)))
        {
            DrawWindowHeader();
            DrawBuildActions();
            GUILayout.Space(4);
            using(var viewport=new EditorGUILayout.ScrollViewScope(scroll,GUILayout.MinWidth(0f),GUILayout.MinHeight(0f),GUILayout.ExpandHeight(true)))
            {
                scroll=viewport.scrollPosition;scroll.x=0;
                if(UiSection("Build status"+(string.IsNullOrEmpty(lastBuildError)?"":" - error"),ref showStatus,status))
                {
                    UiHelp(status,string.IsNullOrEmpty(lastBuildError)?MessageType.Info:MessageType.Error);
                    using(new EditorGUI.DisabledScope(string.IsNullOrEmpty(lastBuildError)))
                        if(UiButton(UiRow(25),"Copy last build error","Copy the full error and stack trace."))EditorGUIUtility.systemCopyBuffer=lastBuildError;
                }
                GUILayout.Space(4);
                if(UiSection("Floors",ref showFloors,"Show all floors, isolate one floor, or control each floor independently."))
                {
                    DrawFloorPresets();
                    for(int f=1;f<=FloorCount;f++)DrawFloor(f);
                }
                if(UiSection("Roofs",ref showRoofs,"Control the entire roof group or an individual roof."))DrawRoofs();
                if(UiSection("Scene options",ref showSceneOptions,"Room labels, stair connections and exterior ground."))DrawSite();
                if(UiSection("Generation settings",ref showSettings,"These values apply when you generate the building again."))DrawGenerationSettings();
                if(UiSection("Help and plan notes",ref showHelp,"Visibility controls, drawing assumptions and source-plan notes."))
                {
                    UiHelp("Active disables the group and its colliders. Render hides its geometry. Reference shows the registered plan overlay. Top and Focus move the Scene view. Despawn removes a floor and its stair connections; use Undo or generate again to restore it.",MessageType.None);
                    UiHelp("Floor-only views include the stairs arriving from below. Heights, exterior grade, furniture dimensions and window elevations are estimates. Floor 1 S5 follows the perpendicular drawn flights; verify that physical route on site.",MessageType.None);
                    UiHelp("The model includes six floors, roofs, piano-bay glazing, breezeway vending, the S3 porch and HVAC service access via 212. Resizing this window changes only its controls.",MessageType.None);
                }
            }
        }
        SyncLabels();
    }
    static Rect UiRow(float height)
    {return EditorGUILayout.GetControlRect(false,height,GUILayout.MinWidth(0f),GUILayout.ExpandWidth(true));}
    static int UiColumns(float width,int count,float minimum=84f)
    {return Mathf.Clamp(Mathf.FloorToInt((width+4f)/(minimum+4f)),1,count);}
    static Rect UiCell(Rect row,int index,int columns)
    {
        float width=Mathf.Max(1f,(row.width-4f*(columns-1))/columns);
        return new Rect(row.x+index*(width+4f),row.y,width,row.height);
    }
    static Rect UiWeightedCell(Rect row,int index,float[] weights)
    {
        float unit=Mathf.Max(1f,row.width-4f*(weights.Length-1))/weights.Sum(),x=row.x;
        for(int i=0;i<index;i++)x+=weights[i]*unit+4f;
        return new Rect(x,row.y,weights[index]*unit,row.height);
    }
    bool UiButton(Rect rect,string text,string tooltip)
    {return GUI.Button(rect,new GUIContent(text,tooltip),uiButton);}
    bool UiToggle(Rect rect,string text,bool value,string tooltip)
    {return GUI.Toggle(rect,value,new GUIContent(text,tooltip),EditorStyles.miniButton);}
    bool UiSection(string title,ref bool expanded,string tooltip)
    {
        GUILayout.Space(5);
        bool next=EditorGUI.Foldout(UiRow(24),expanded,new GUIContent(title,tooltip),true,EditorStyles.foldoutHeader);
        if(next!=expanded){expanded=next;Repaint();GUIUtility.ExitGUI();}
        return expanded;
    }
    void UiText(string text,GUIStyle style)
    {
        GUIContent content=new GUIContent(text);
        float height=Mathf.Max(EditorGUIUtility.singleLineHeight,style.CalcHeight(content,Mathf.Max(1f,uiLayoutWidth)));
        GUI.Label(UiRow(height),content,style);
    }
    void UiHelp(string text,MessageType type)
    {
        if(string.IsNullOrEmpty(text))return;
        float width=Mathf.Max(1f,uiLayoutWidth-(type==MessageType.None?12f:44f));
        float height=Mathf.Max(30f,EditorStyles.helpBox.CalcHeight(new GUIContent(text),width)+12f);
        EditorGUI.HelpBox(UiRow(height),text,type);
    }
    float UiFloat(string label,float value,string tooltip)
    {
        GUIContent content=new GUIContent(label,tooltip);
        if(uiLayoutWidth<400f)
        {
            UiText(label,EditorStyles.wordWrappedLabel);
            return EditorGUI.FloatField(UiRow(22),value);
        }
        Rect row=UiRow(22);float old=EditorGUIUtility.labelWidth;
        try{EditorGUIUtility.labelWidth=Mathf.Min(row.width*.62f,290f);return EditorGUI.FloatField(row,content,value);}
        finally{EditorGUIUtility.labelWidth=old;}
    }
    bool UiBool(string label,bool value,string tooltip)
    {return EditorGUI.ToggleLeft(UiRow(23),new GUIContent(label,tooltip),value);}
    void DrawWindowHeader()
    {
        Rect row=UiRow(24);
        GUI.Label(new Rect(row.x,row.y,Mathf.Max(1f,row.width-70),row.height),"Building 9",EditorStyles.boldLabel);
        GUI.Label(new Rect(Mathf.Max(row.x,row.xMax-62),row.y,62,row.height),"v6.13.1",EditorStyles.miniLabel);
        int present=0;for(int n=1;n<=FloorCount;n++)if(FloorRoot(n)!=null)present++;
        UiText("Scene: "+present+" / "+FloorCount+" floors generated",EditorStyles.wordWrappedMiniLabel);
        if(!string.IsNullOrEmpty(lastBuildError))
        {
            Rect error=UiRow(24);float button=Mathf.Min(110f,error.width*.45f);
            GUI.Label(new Rect(error.x,error.y,error.width-button-4,error.height),new GUIContent("Build stopped",status),EditorStyles.boldLabel);
            if(UiButton(new Rect(error.xMax-button,error.y,button,error.height),"Copy error","Copy the full build error."))EditorGUIUtility.systemCopyBuffer=lastBuildError;
        }
        else if(working||queuedOperation!=0)UiText("Working: "+buildStage,EditorStyles.wordWrappedMiniLabel);
        if(IsPlaySession)UiText("Play Mode: visibility is temporary. Stop to generate or despawn.",EditorStyles.wordWrappedMiniLabel);
    }
    void DrawBuildActions()
    {
        using(new EditorGUI.DisabledScope(working||queuedOperation!=0||IsPlaySession))
        {
            if(uiLayoutWidth>=460f)
            {
                Rect row=UiRow(34);float[] weights={2f,1f};
                if(UiButton(UiWeightedCell(row,0,weights),"Generate / replace building","Generate all six floors and roofs. Replaces the generated building and supports Undo."))QueueOperation(1);
                if(UiButton(UiWeightedCell(row,1,weights),"Validate plans","Check the embedded plans without replacing scene objects."))QueueOperation(2);
            }
            else
            {
                if(UiButton(UiRow(34),"Generate / replace building","Generate all six floors and roofs. Replaces the generated building and supports Undo."))QueueOperation(1);
                if(UiButton(UiRow(25),"Validate plans","Check the embedded plans without replacing scene objects."))QueueOperation(2);
            }
        }
    }
    void DrawFloorPresets()
    {
        using(new EditorGUI.DisabledScope(FindBuilding()==null||working||queuedOperation!=0))
        {
            if(uiLayoutWidth>=640f)
            {
                Rect row=UiRow(28);
                if(UiButton(UiCell(row,0,7),"All floors","Show all floors and their stair connections."))Preset(0);
                for(int n=1;n<=FloorCount;n++)if(UiButton(UiCell(row,n,7),"Floor "+n,"Show only Floor "+n+" and its arriving/departing stairs."))Preset(n);
            }
            else
            {
                if(UiButton(UiRow(26),"All floors","Show all floors and their stair connections."))Preset(0);
                int maximum=UiColumns(uiLayoutWidth,FloorCount),rows=Mathf.CeilToInt((float)FloorCount/maximum);
                int columns=Mathf.CeilToInt((float)FloorCount/rows);
                for(int start=1;start<=FloorCount;start+=columns)
                {
                    Rect row=UiRow(26);
                    for(int c=0;c<columns&&start+c<=FloorCount;c++)
                    {int n=start+c;if(UiButton(UiCell(row,c,columns),"Floor "+n,"Show only Floor "+n+" and its arriving/departing stairs."))Preset(n);}
                }
            }
        }
        GUILayout.Space(5);
    }
    void DrawFloor(int n)
    {
        Transform t=FloorRoot(n);
        bool compact=uiLayoutWidth<620f;int columns=UiColumns(Mathf.Max(1f,uiLayoutWidth-12f),3);
        int rows=Mathf.CeilToInt(3f/columns);
        GUIContent title=new GUIContent("Floor "+n+(compact&&t==null?" - not generated":""));
        float titleHeight=compact?Mathf.Max(22f,uiCardTitle.CalcHeight(title,Mathf.Max(1f,uiLayoutWidth-12f))):24f;
        Rect card=UiRow(compact?titleHeight+16f+56f*rows:36f);GUI.Box(card,GUIContent.none,EditorStyles.helpBox);
        Rect inner=new Rect(card.x+6,card.y+6,Mathf.Max(1f,card.width-12),24);
        Rect[] cells=new Rect[7];
        if(compact)
        {
            cells[0]=new Rect(inner.x,inner.y,inner.width,titleHeight);
            for(int i=0;i<3;i++)
            {
                Rect flags=new Rect(inner.x,inner.y+titleHeight+4+(i/columns)*28,inner.width,24);
                Rect actions=new Rect(inner.x,inner.y+titleHeight+6+rows*28+(i/columns)*28,inner.width,24);
                cells[i+1]=UiCell(flags,i%columns,columns);cells[i+4]=UiCell(actions,i%columns,columns);
            }
        }
        else
        {
            float[] weights={1.15f,1f,1f,1.35f,.8f,.9f,1.1f};
            for(int i=0;i<cells.Length;i++)cells[i]=UiWeightedCell(inner,i,weights);
        }
        GUI.Label(cells[0],title,uiCardTitle);
        using(new EditorGUI.DisabledScope(t==null||working||queuedOperation!=0))
        {
            bool active=t!=null&&t.gameObject.activeSelf;
            bool next=UiToggle(cells[1],"Active",active,"Enable this floor and its colliders. Stair connections have their own control.");
            if(t!=null&&next!=active){RecordSceneChange(t.gameObject,"Floor visibility");t.gameObject.SetActive(next);Dirty();}
            Transform reference=t!=null?t.Find("Reference overlay"):null;
            bool rendered=t!=null&&t.GetComponentsInChildren<Renderer>(true).Any(r=>r.enabled&&r.GetComponent<TextMesh>()==null&&(reference==null||!r.transform.IsChildOf(reference)));
            bool render=UiToggle(cells[2],"Render",rendered,"Show or hide this floor's renderers while retaining its active state and colliders.");
            if(t!=null&&render!=rendered)Render(t,render);
            bool shown=reference!=null&&reference.gameObject.activeSelf;
            bool show=UiToggle(cells[3],"Reference",shown,"Show the registered source plan overlay; it has no collider.");
            if(reference!=null&&show!=shown)
            {
                RecordSceneChange(reference.gameObject,"Source reference visibility");reference.gameObject.SetActive(show);
                Renderer renderer=reference.GetComponent<Renderer>();if(renderer!=null){RecordSceneChange(renderer,"Reference rendering");renderer.enabled=show;}
                Dirty();
            }
            if(UiButton(cells[4],"Top","Frame this floor from above in the Scene view.")&&t!=null)
            {Selection.activeGameObject=t.gameObject;SceneView view=SceneView.lastActiveSceneView;if(view!=null){view.rotation=Quaternion.Euler(90,0,0);view.orthographic=true;view.FrameSelected();}}
            if(UiButton(cells[5],"Focus","Frame this floor in the Scene view.")&&t!=null)
            {Selection.activeGameObject=t.gameObject;SceneView.lastActiveSceneView?.FrameSelected();}
            using(new EditorGUI.DisabledScope(IsPlaySession))
                if(UiButton(cells[6],"Despawn","Remove this floor and its departing stairs. Undo or regenerate to restore it.")&&t!=null)QueueOperation(100+n);
        }
        GUILayout.Space(3);
    }
    void DrawRoofs()
    {
        GameObject building=FindBuilding();Transform root=building!=null?building.transform.Find("Roofs"):null;
        bool visible=UiBool("Show roof group",roofsVisible,"Show or hide every generated roof.");
        if(visible!=roofsVisible)
        {roofsVisible=visible;if(root!=null){RecordSceneChange(root.gameObject,"Roof visibility");root.gameObject.SetActive(visible);Dirty();}}
        Roof[] definitions=runtimePlans!=null&&runtimePlans.roofs!=null?runtimePlans.roofs:new Roof[0];
        using(new EditorGUI.DisabledScope(root==null||working||queuedOperation!=0))foreach(Roof roof in definitions)
        {
            Transform part=root!=null?root.Find(roof.name):null;
            bool compact=uiLayoutWidth<520f;int columns=UiColumns(Mathf.Max(1f,uiLayoutWidth-12f),2);
            int rows=Mathf.CeilToInt(2f/columns);
            GUIContent title=new GUIContent(roof.name,roof.name);
            float titleHeight=compact?Mathf.Max(22f,uiCardTitle.CalcHeight(title,Mathf.Max(1f,uiLayoutWidth-12f))):24f;
            Rect card=UiRow(compact?titleHeight+12f+28f*rows:36f);GUI.Box(card,GUIContent.none,EditorStyles.helpBox);
            Rect inner=new Rect(card.x+6,card.y+6,Mathf.Max(1f,card.width-12),24),name,activeRect,renderRect;
            if(compact)
            {
                name=new Rect(inner.x,inner.y,inner.width,titleHeight);
                activeRect=UiCell(new Rect(inner.x,inner.y+titleHeight+4,inner.width,24),0,columns);
                renderRect=UiCell(new Rect(inner.x,inner.y+titleHeight+4+(1/columns)*28,inner.width,24),1%columns,columns);
            }
            else
            {float[] weights={3f,1f,1f};name=UiWeightedCell(inner,0,weights);activeRect=UiWeightedCell(inner,1,weights);renderRect=UiWeightedCell(inner,2,weights);}
            GUI.Label(name,title,uiCardTitle);
            bool active=part!=null&&part.gameObject.activeSelf;
            bool next=UiToggle(activeRect,"Active",active,"Enable this roof and its colliders.");
            if(part!=null&&next!=active){RecordSceneChange(part.gameObject,"Roof active");part.gameObject.SetActive(next);Dirty();}
            bool rendered=part!=null&&part.GetComponentsInChildren<Renderer>(true).Any(r=>r.enabled);
            bool render=UiToggle(renderRect,"Render",rendered,"Show or hide this roof's renderers.");if(part!=null&&render!=rendered)Render(part,render);
            GUILayout.Space(3);
        }
    }
    void DrawSite()
    {
        bool labels=UiBool("Room labels on highest shown floor",roomLabels,"Show room labels on the highest visible floor.");
        if(labels!=roomLabels){roomLabels=labels;SyncLabels();Dirty();}
        GameObject root=FindBuilding();Transform stairs=root!=null?root.transform.Find("Stair connections"):null;
        using(new EditorGUI.DisabledScope(stairs==null||working||queuedOperation!=0))
        {
            bool active=stairs!=null&&stairs.gameObject.activeSelf,next=UiBool("Stair connections",active,"Enable all stair connections and their colliders.");
            if(stairs!=null&&next!=active){RecordSceneChange(stairs.gameObject,"Stair connections");stairs.gameObject.SetActive(next);Dirty();}
        }
        Transform site=root!=null?root.transform.Find("Site"):null;
        using(new EditorGUI.DisabledScope(site==null||working||queuedOperation!=0))
        {
            bool active=site!=null&&site.gameObject.activeSelf,next=UiBool("Exterior ground and paths",active,"Enable the generated site group and its colliders.");
            if(site!=null&&next!=active){RecordSceneChange(site.gameObject,"Site active");site.gameObject.SetActive(next);Dirty();}
        }
    }
