        foreach(float x in new[]{-1.65f,-1.35f})foreach(float z in new[]{-.28f,.28f})Box(parent,"Bench leg",new Vector3(x,.2f,z),new Vector3(.045f,.4f,.045f),"Piano",colliders);
    }
    Material PrepareReference(Floor f)
    {
        string path=Folder+"/Floor"+f.number+"Reference.png";
        byte[] bytes=Convert.FromBase64String(f.reference);
        if(!File.Exists(path)||!File.ReadAllBytes(path).SequenceEqual(bytes)){File.WriteAllBytes(path,bytes);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceUpdate);}
        TextureImporter importer=AssetImporter.GetAtPath(path) as TextureImporter;
        if(importer!=null && (importer.mipmapEnabled||importer.maxTextureSize<2048||importer.textureCompression!=TextureImporterCompression.Uncompressed))
        {importer.mipmapEnabled=false;importer.maxTextureSize=4096;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.SaveAndReimport();}
        Texture2D texture=AssetDatabase.LoadAssetAtPath<Texture2D>(path);
        string matpath=Folder+"/Floor"+f.number+"Reference.mat";Material mat=AssetDatabase.LoadAssetAtPath<Material>(matpath);
        if(texture==null)throw new InvalidOperationException("Floor "+f.number+" source texture failed to import.");
        if(mat==null){Shader sh=Shader.Find("Universal Render Pipeline/Unlit")??Shader.Find("Unlit/Texture");if(sh==null)throw new InvalidOperationException("A reference texture shader is missing.");mat=new Material(sh);AssetDatabase.CreateAsset(mat,matpath);}
        mat.mainTexture=texture;if(mat.HasProperty("_BaseMap"))mat.SetTexture("_BaseMap",texture);if(mat.HasProperty("_BaseColor"))mat.SetColor("_BaseColor",Color.white);EditorUtility.SetDirty(mat);
        return mat;
    }
    void BuildReference(Transform level,Floor f)
    {
        if(!referenceMaterials.TryGetValue(f.number,out Material mat)||mat==null)
            throw new InvalidOperationException("Floor "+f.number+" source reference was not prepared.");
        Transform t=Group("Reference overlay",level);
        Mesh mesh=Surface(f.refMesh,.035f);var uv=new Vector2[f.refUV.Length/2];for(int i=0;i<uv.Length;i++)uv[i]=new Vector2(f.refUV[i*2],f.refUV[i*2+1]);mesh.uv=uv;
        t.gameObject.AddComponent<MeshFilter>().sharedMesh=Persist(mesh,"Floor"+f.number+"Reference");t.gameObject.AddComponent<MeshRenderer>().sharedMaterial=mat;t.gameObject.SetActive(false);
    }
    void BuildRoofs(Transform building)
    {
        Transform roofs=Group("Roofs",building);
        foreach(Roof roof in Data().roofs)
        {
            Transform cap=Group(roof.name,roofs);cap.localPosition=Vector3.up*(roof.aboveFloor*floorHeight);
            string key="RoofAbove"+roof.aboveFloor;
            MeshObject(cap,"Structural roof slab",Extrude(roof.slab,-roofSlabDepth,p=>0),"Roof concrete",key+"_Slab",colliders);
            if(roof.membrane.t.Length>0)MeshObject(cap,"Roof membrane",Surface(roof.membrane,.006f),"Roof membrane",key+"_Membrane",false);
            if(roof.zone.t.Length>0)MeshObject(cap,"Plan-shaded roof surface",Surface(roof.zone,.006f),"Roof shaded zone",key+"_Zone",false);
            float h=roofParapetHeight*roof.parapetScale;
            if(roof.parapet.t.Length>0)
            {
                MeshObject(cap,"Low perimeter parapet",Extrude(roof.parapet,0,p=>h),"Facade white",key+"_Parapet",colliders);
                MeshObject(cap,"Parapet coping",Extrude(roof.coping,h,p=>h+.055f),"Roof coping",key+"_Coping",colliders);
            }
        }
        roofs.gameObject.SetActive(roofsVisible);
    }
    void BuildSite(Transform site)
    {
        // North grade and all furnishings share Floor 2's registered level.
        // Dimensions inferred from the two photographs remain estimates.
        Box(site,"Lower west ground and exterior room approaches",new Vector3(30.25f,-.17f,19),new Vector3(64.5f,.3f,42),"Terrain",colliders);
        BuildNorthForecourt(site,Data().northSite);
    }
    void BuildNorthForecourt(Transform site,NorthSite plan)
    {
        Transform court=Group("North forecourt",site);court.localPosition=Vector3.up*floorHeight;
        MeshObject(court,"Raised grade supporting the north entrance",Extrude(plan.ground,-floorHeight-.22f,p=>-.025f),"Terrain","North_Grade",colliders);
        MeshObject(court,"Connected concrete entrance plaza",Extrude(plan.paving,-.16f,p=>0),"Concrete","North_Plaza",colliders);
        if(plan.thresholdPaving.t.Length>0)
            MeshObject(court,"Concrete finish on grade-level entrance aprons",Surface(plan.thresholdPaving,.006f),"Concrete","North_EntranceAprons",false);
        MeshObject(court,"Rectangular patio inside L railing",Extrude(plan.patio,-.16f,p=>0),"Patio concrete","North_Patio",colliders);
        MeshObject(court,"North lawn",Surface(plan.lawn,0),"Lawn","North_Lawn",false);
        MeshObject(court,"Mulch planting beds",Extrude(plan.beds,-.06f,p=>.025f),"Mulch","North_Beds",false);
        Transform fencing=Group("L-shaped patio fence - entrance side open",court);
        var fencePosts=new HashSet<Vector2Int>();
        foreach(SiteFence edge in plan.fence)BuildPatioFence(fencing,edge,fencePosts);
        Transform tables=Group("Two fenced patio table sets",court);
        for(int i=0;i<plan.patioTables.Length;i++)BuildOutdoorTable(tables,plan.patioTables[i],"Patio table "+(i+1),false,false,true);
        Transform perimeterSeats=Group("Backless benches along patio wall and railing",court);
        foreach(SiteBench bench in plan.patioBenches)BuildBacklessBench(perimeterSeats,bench);
        Transform edgeSeats=Group("Backless benches at curved lawn edge",court);
        foreach(SiteBench bench in plan.edgeBenches)BuildBacklessBench(edgeSeats,bench);
        MeshObject(court,"Curved grass and path edging",Extrude(plan.lawnBorder,-.04f,p=>.035f),"Concrete","North_LawnEdging",false);
        Transform publicTables=Group("Forecourt round tables and benches",court);
        for(int i=0;i<plan.plazaTables.Length;i++)BuildOutdoorTable(publicTables,plan.plazaTables[i],"Plaza table "+(i+1),i<2,i==3);
        Transform planting=Group("Trees hedges and planting beds",court);
        foreach(SiteTree tree in plan.trees)BuildForecourtTree(planting,tree);
        foreach(SiteHedge hedge in plan.hedges)
        {
            Box(planting,"Clipped hedge",new Vector3(hedge.x,hedge.height/2,hedge.z),new Vector3(hedge.width,hedge.height,hedge.depth),"Hedge",false);
            int clusters=Mathf.Max(3,Mathf.CeilToInt(hedge.depth/.55f));
            for(int i=0;i<clusters;i++)
                SiteLeafCluster(planting,new Vector3(hedge.x,hedge.height*.80f,hedge.z-hedge.depth/2+(i+.5f)*hedge.depth/clusters),
                    new Vector3(hedge.width*1.08f,hedge.height*.42f,hedge.depth/clusters*1.25f),"Hedge");
        }
        Transform fixtures=Group("Bins and entrance wayfinding",court);
        foreach(SiteFixture fixture in plan.fixtures)BuildSiteFixture(fixtures,fixture);
        BuildEntranceStatue(court,plan.statue);
        BuildWallMountedIdentification(site.parent,plan);
        // The open patio edge has no railing, gate, curb, or change of level.
        // Keep every surface in the same frame and at Floor 2 finished level.
    }
    void BuildEntranceStatue(Transform court,SiteStatue definition)
    {
        Transform display=Group("Photo-reference entrance statue",court);
        display.localPosition=new Vector3(definition.x,0,definition.z);
        Transform sculpture=Group("Open metal figure on tapered plinth",display);
        sculpture.localRotation=Quaternion.Euler(0,definition.yaw,0);
        // Approximate the visible open silhouette; no unverified title or
        // plaque inscription is invented from the low-resolution photo.
        var v=new List<Vector3>();
        foreach(float y in new[]{-.025f,.56f})
        {
            float x=y<0?.41f:.235f,z=y<0?.38f:.215f;
            v.Add(new Vector3(-x,y,-z));v.Add(new Vector3(x,y,-z));v.Add(new Vector3(x,y,z));v.Add(new Vector3(-x,y,z));
        }
        var indices=new List<int>{0,1,2,0,2,3,4,6,5,4,7,6};
        for(int i=0;i<4;i++){int j=(i+1)%4;indices.AddRange(new[]{i,i+4,j+4,i,j+4,j});}
        var flatV=new List<Vector3>();var flatT=new List<int>();
        foreach(int i in indices){flatT.Add(flatV.Count);flatV.Add(v[i]);}
        MeshObject(sculpture,"Tapered concrete statue pedestal",MakeMesh(flatV,flatT),"Concrete","North_StatuePlinth",colliders);
        GameObject plaque=Box(sculpture,"Small unlettered plaque",new Vector3(0,.32f,.292f),new Vector3(.26f,.14f,.016f),"Statue bronze",false);
        plaque.transform.localRotation=Quaternion.Euler(-15.8f,0,0);
        OutdoorBar(sculpture,"Sculpture support stem",new Vector3(0,.56f,0),new Vector3(0,.89f,0),.036f,"Statue bronze",colliders);
        Vector3 left=new Vector3(-.22f,.89f,0),right=new Vector3(.22f,.89f,0),peak=new Vector3(.015f,1.40f,0);
        OutdoorBar(sculpture,"Open figure left outline",left,peak,.035f,"Statue bronze",false);
        OutdoorBar(sculpture,"Open figure right outline",peak,right,.035f,"Statue bronze",false);
        OutdoorBar(sculpture,"Figure lower crosspiece",left,right,.035f,"Statue bronze",false);
        OutdoorBar(sculpture,"Figure shoulder detail",peak,new Vector3(-.14f,1.35f,.01f),.028f,"Statue bronze",false);
        OutdoorBar(sculpture,"Short figure neck",peak,new Vector3(.015f,1.46f,0),.028f,"Statue bronze",false);
        const int loops=32,sides=8;var headV=new List<Vector3>();var headT=new List<int>();
        for(int ring=0;ring<loops;ring++)for(int side=0;side<sides;side++)
        {
            float theta=ring*Mathf.PI*2/loops,phi=side*Mathf.PI*2/sides;
            float radius=.077f+.014f*Mathf.Cos(phi);
            headV.Add(new Vector3(.015f+Mathf.Cos(theta)*radius,1.535f+Mathf.Sin(theta)*radius*1.12f,.014f*Mathf.Sin(phi)));
        }
        for(int ring=0;ring<loops;ring++)for(int side=0;side<sides;side++)
        {
            int a=ring*sides+side,b=((ring+1)%loops)*sides+side,c=((ring+1)%loops)*sides+(side+1)%sides,d=ring*sides+(side+1)%sides;
            headT.AddRange(new[]{a,b,c,a,c,d});
        }
        MeshObject(sculpture,"Looped head of abstract figure",MakeMesh(headV,headT),"Statue bronze","North_StatueLoop",false);
        var random=new System.Random(909);
        for(int i=0;i<28;i++)
        {
            float angle=i*Mathf.PI*2/28,radius=.78f+(float)random.NextDouble()*.17f;
            Vector3 p=new Vector3(Mathf.Cos(angle)*1.02f*radius,.10f,Mathf.Sin(angle)*.62f*radius);
            SiteLeafCluster(display,p,new Vector3(.30f,.19f,.25f),"Hedge");
            SiteLeafCluster(display,p+Vector3.up*.105f,new Vector3(.16f,.11f,.15f),i%3==0?"Flower rose":"Flower burgundy");
        }
    }
    static Bounds RendererBoundsIn(Transform frame,Renderer renderer)
    {
        Bounds world=renderer.bounds;
        Bounds local=new Bounds(frame.InverseTransformPoint(world.center),Vector3.zero);
        foreach(int x in new[]{-1,1})foreach(int y in new[]{-1,1})foreach(int z in new[]{-1,1})
            local.Encapsulate(frame.InverseTransformPoint(world.center+Vector3.Scale(world.extents,new Vector3(x,y,z))));
        return local;
    }
    void BuildWallMountedIdentification(Transform generatedRoot,NorthSite plan)
    {
        Transform level=generatedRoot.Find("Floor 2"),walls=level.Find("Traced walls");
        float width=plan.buildingSign[4],height=plan.buildingSign[5],panelWidth=width+.16f,panelHeight=height+.16f;
        float y=Mathf.Clamp(plan.buildingSign[2],panelHeight/2+.08f,floorHeight-floorSlabDepth-panelHeight/2-.08f);
        Vector3 position=new Vector3(plan.buildingSign[0],y,plan.buildingSign[1]);
        if(colliders)
        {
            Physics.SyncTransforms();
            Vector3 outward=level.TransformDirection(Vector3.right).normalized;
            Vector3 start=level.TransformPoint(position+Vector3.right*.60f);float distance=float.PositiveInfinity;bool found=false;
            foreach(Collider wall in walls.GetComponentsInChildren<Collider>(true))
                if(wall.Raycast(new Ray(start,-outward),out RaycastHit hit,1.25f*buildingScale)&&hit.distance<distance)
                {distance=hit.distance;position=level.InverseTransformPoint(hit.point)+Vector3.right*.004f;found=true;}
            if(!found)throw new InvalidOperationException("No solid wall behind the Engineering 9 lettering. The previous building was kept.");
        }
        Transform mount=Group("Wall-mounted Engineering 9 lettering",walls);
        mount.localPosition=position;mount.localRotation=Quaternion.Euler(0,-90,0);
        // The thin wall-coloured mount touches the sampled facade; the text
        // fits its entire support area and cannot span a doorway recess.
        Box(mount,"Flush wall-coloured lettering mount",new Vector3(0,0,.004f),new Vector3(panelWidth,panelHeight,.016f),"Wall",false);
        OutdoorText(mount,"Engineering 9 letters","ENGINEERING\n9",new Vector3(0,0,-.014f),0,plan.buildingSign[3],new Color(.18f,.19f,.20f));
        Transform letters=mount.Find("Engineering 9 letters");TextMesh text=letters.GetComponent<TextMesh>();Renderer renderer=letters.GetComponent<Renderer>();
        for(int pass=0;pass<2;pass++)
        {
            Bounds bounds=RendererBoundsIn(mount,renderer);
            float fit=Mathf.Min(1,Mathf.Min(width/Mathf.Max(bounds.size.x,.001f),height/Mathf.Max(bounds.size.y,.001f)));
            text.characterSize*=fit;
        }
        Bounds finalBounds=RendererBoundsIn(mount,renderer);
        letters.localPosition-=new Vector3(finalBounds.center.x,finalBounds.center.y,0);
    }
    void CheckWallMountedIdentification(Transform generatedRoot)
    {
        Transform walls=generatedRoot.Find("Floor 2/Traced walls"),mount=walls.Find("Wall-mounted Engineering 9 lettering");
        if(mount==null)throw new InvalidOperationException("Wall-mounted building identification is missing.");
        NorthSite plan=Data().northSite;
        Collider[] solids=walls.GetComponentsInChildren<Collider>(true);
        foreach(float x in new[]{-.5f,0,.5f})foreach(float y in new[]{-.5f,0,.5f})
        {
            Vector3 p=new Vector3(x*(plan.buildingSign[4]+.16f),y*(plan.buildingSign[5]+.16f),0);
            Vector3 a=mount.TransformPoint(p-Vector3.forward*.10f),b=mount.TransformPoint(p+Vector3.forward*.32f);
            if(!solids.Any(w=>WallCrossesSegment(w,a,b)))
                throw new InvalidOperationException("Building lettering extends beyond its supporting wall. The previous building was kept.");
        }
    }
    void BuildPatioFence(Transform parent,SiteFence edge,HashSet<Vector2Int> fencePosts)
    {
        Transform run=Group("Dark steel fence run",parent);
        Vector3 a=new Vector3(edge.a[0],0,edge.a[1]),b=new Vector3(edge.b[0],0,edge.b[1]);
        foreach(float y in new[]{.13f,.98f})OutdoorBar(run,"Horizontal fence rail",a+Vector3.up*y,b+Vector3.up*y,.042f,"Outdoor steel",colliders);
        int posts=Mathf.Max(1,Mathf.CeilToInt(Vector3.Distance(a,b)/1.35f));
        for(int i=0;i<=posts;i++)
        {
            Vector3 foot=Vector3.Lerp(a,b,(float)i/posts);
            if(!fencePosts.Add(new Vector2Int(Mathf.RoundToInt(foot.x*1000),Mathf.RoundToInt(foot.z*1000))))continue;
            OutdoorBar(run,"Fence post",foot,foot+Vector3.up*1.06f,.065f,"Outdoor steel",colliders);
            Box(run,"Fence post cap",foot+Vector3.up*1.065f,Vector3.one*.084f,"Outdoor steel",false);
        }
        int pickets=Mathf.Max(2,Mathf.CeilToInt(Vector3.Distance(a,b)/.115f));
        for(int i=1;i<pickets;i++)
        {
            Vector3 foot=Vector3.Lerp(a,b,(float)i/pickets)+Vector3.up*.13f;
            OutdoorBar(run,"Vertical fence picket",foot,foot+Vector3.up*.85f,.021f,"Outdoor steel",colliders);
        }
    }
    void OutdoorBar(Transform parent,string name,Vector3 a,Vector3 b,float width,string material,bool solid)
    {
        Vector3 delta=b-a;if(delta.sqrMagnitude<.000001f)return;
        GameObject go=Box(parent,name,(a+b)/2,new Vector3(width,delta.magnitude,width),material,solid);
        go.transform.localRotation=Quaternion.FromToRotation(Vector3.up,delta.normalized);
    }
    void BuildOutdoorTable(Transform parent,PicnicTable table,string name,bool umbrella,bool openSeat,bool builtInBenches=true)
    {
        Transform furniture=Group(name,parent);furniture.localPosition=new Vector3(table.x,0,table.z);
        furniture.localScale=Vector3.one*(table.radius/1.20f);
        CylinderPiece(furniture,"Round metal tabletop",new Vector3(0,.75f,0),new Vector3(1.48f,.025f,1.48f),"Outdoor steel",colliders);
        CylinderPiece(furniture,"Central pedestal",new Vector3(0,.37f,0),new Vector3(.16f,.37f,.16f),"Outdoor steel",colliders);
        CylinderPiece(furniture,"Pedestal base",new Vector3(0,.035f,0),new Vector3(.42f,.035f,.42f),"Outdoor steel",colliders);
        for(int seat=0;seat<(builtInBenches?4:0);seat++)
        {
            if(openSeat&&seat==0)continue;
            float angle=seat*90f;
            MeshObject(furniture,"Curved metal bench "+(seat+1),Extrude(BenchSector(.93f,1.20f,angle),.425f,p=>.475f),"Outdoor steel","North_"+name+"_Bench"+seat,colliders);
            foreach(float offset in new[]{-18f,18f})
            {
                float radians=(angle+offset)*Mathf.Deg2Rad;
                Vector3 foot=new Vector3(Mathf.Cos(radians)*1.065f,0,Mathf.Sin(radians)*1.065f);
                OutdoorBar(furniture,"Bench support",foot,foot+Vector3.up*.43f,.055f,"Outdoor steel",colliders);
            }
            float a=angle*Mathf.Deg2Rad;
            OutdoorBar(furniture,"Low radial table support",Vector3.up*.15f,new Vector3(Mathf.Cos(a)*1.06f,.15f,Mathf.Sin(a)*1.06f),.045f,"Outdoor steel",colliders);
        }
        if(umbrella)BuildPatioUmbrella(furniture);
    }
    void BuildBacklessBench(Transform parent,SiteBench bench)
    {
        Transform seat=Group(bench.name,parent);
        Vector3 a=new Vector3(bench.a[0],0,bench.a[1]),b=new Vector3(bench.b[0],0,bench.b[1]);
        float length=Vector3.Distance(a,b);
        seat.localPosition=(a+b)/2;seat.localRotation=Quaternion.LookRotation(b-a);
        // Flat slatted seats only. Benches follow the wall/rail/lawn edges;
        // no backrest, armrest or separate table-mounted seats are added.
        const int slats=5;float slat=bench.width/slats;
        for(int i=0;i<slats;i++)
            Box(seat,"Flat seat slat",new Vector3(-bench.width/2+(i+.5f)*slat,bench.height-.0275f,0),
                new Vector3(slat-.008f,.055f,length),"Outdoor steel",colliders);
        int supports=Mathf.Max(2,Mathf.CeilToInt(length/1.4f)+1);
        for(int i=0;i<supports;i++)
        {
            float z=Mathf.Lerp(-length/2+.18f,length/2-.18f,(float)i/(supports-1));
            foreach(int side in new[]{-1,1})
                OutdoorBar(seat,"Bench leg",new Vector3(side*bench.width*.32f,0,z),
                    new Vector3(side*bench.width*.32f,bench.height-.055f,z),.055f,"Outdoor steel",colliders);
            OutdoorBar(seat,"Seat cross support",new Vector3(-bench.width*.42f,bench.height-.075f,z),
                new Vector3(bench.width*.42f,bench.height-.075f,z),.045f,"Outdoor steel",colliders);
        }
    }
    void BuildPatioUmbrella(Transform table)
    {
        Transform canopy=Group("Tan patio umbrella",table);
        CylinderPiece(canopy,"Umbrella mast",new Vector3(0,1.36f,0),new Vector3(.045f,1.36f,.045f),"Outdoor steel",colliders);
        var vertices=new List<Vector3>();var triangles=new List<int>();const int sectors=8;
        vertices.Add(new Vector3(0,2.78f,0));
        for(int i=0;i<sectors;i++)
        {
            float angle=i*Mathf.PI*2/sectors;
            vertices.Add(new Vector3(Mathf.Cos(angle)*1.34f,2.32f,Mathf.Sin(angle)*1.34f));
        }
        for(int i=0;i<sectors;i++)
        {
            int a=0,b=i+1,c=(i+1)%sectors+1;
            // Both faces are visible without depending on a pipeline-specific
            // double-sided material setting.
            triangles.Add(a);triangles.Add(b);triangles.Add(c);triangles.Add(a);triangles.Add(c);triangles.Add(b);
            OutdoorBar(canopy,"Umbrella rib",vertices[a]-Vector3.up*.015f,vertices[b]-Vector3.up*.015f,.012f,"Outdoor steel",false);
        }
        var separateVertices=new List<Vector3>();var separateTriangles=new List<int>();
        foreach(int index in triangles){separateTriangles.Add(separateVertices.Count);separateVertices.Add(vertices[index]);}
        MeshObject(canopy,"Canvas shade",MakeMesh(separateVertices,separateTriangles),"Umbrella canvas","North_Umbrella",false);
    }
    void SiteLeafCluster(Transform parent,Vector3 centre,Vector3 size,string material)
    {
        GameObject leaf=GameObject.CreatePrimitive(PrimitiveType.Sphere);leaf.name="Foliage cluster";
        leaf.transform.SetParent(parent,false);leaf.transform.localPosition=centre;leaf.transform.localScale=size;
        leaf.GetComponent<Renderer>().sharedMaterial=materials[material];DestroyImmediate(leaf.GetComponent<Collider>());
    }
    void TreeBranch(Transform parent,Vector3 a,Vector3 b,float diameter,bool solid)
    {
        Transform branch=Group("Tree branch",parent);branch.localPosition=(a+b)/2;
        branch.localRotation=Quaternion.FromToRotation(Vector3.up,(b-a).normalized);
        CylinderPiece(branch,"Bark",Vector3.zero,new Vector3(diameter,Vector3.Distance(a,b)/2,diameter),"Tree bark",solid);
    }
    void BuildForecourtTree(Transform parent,SiteTree definition)
    {
        Transform tree=Group("Spreading forecourt tree "+definition.seed,parent);tree.localPosition=new Vector3(definition.x,0,definition.z);
        float h=definition.height;
        var random=new System.Random(definition.seed);
        Vector3 fork=new Vector3(.12f,h*.43f,.08f);
        TreeBranch(tree,Vector3.zero,fork,.19f,colliders);
        for(int branch=0;branch<5;branch++)
        {
            float angle=branch*Mathf.PI*2/5+(float)random.NextDouble()*.45f;
            Vector3 tip=new Vector3(Mathf.Cos(angle)*1.65f,h*(.75f+(float)random.NextDouble()*.15f),Mathf.Sin(angle)*1.65f);
            TreeBranch(tree,fork,tip,.095f,false);
            for(int twig=0;twig<4;twig++)
            {
                float azimuth=angle+(twig-1.5f)*.55f;
                Vector3 end=tip+new Vector3(Mathf.Cos(azimuth)*.85f,h*.10f,Mathf.Sin(azimuth)*.85f);
                TreeBranch(tree,Vector3.Lerp(fork,tip,.70f),end,.035f,false);
                SiteLeafCluster(tree,end,new Vector3(1.65f,.64f,1.50f),twig%2==0?"Tree leaves light":"Tree leaves dark");
            }
        }
        // Only trunks collide: small decorative foliage must not create
        // invisible obstacles or block the registered entrance/window probes.
        CylinderPiece(tree,"Low rounded planting-bed rim",new Vector3(0,.025f,0),new Vector3(2.72f,.025f,2.72f),"Concrete",false);
        CylinderPiece(tree,"Exposed mulch inside tree rim",new Vector3(0,.054f,0),new Vector3(2.55f,.008f,2.55f),"Mulch",false);
    }
    void OutdoorText(Transform parent,string name,string content,Vector3 position,float yaw,float size,Color colour)
    {
        Transform t=Group(name,parent);t.localPosition=position;t.localRotation=Quaternion.Euler(0,yaw,0);
        TextMesh text=t.gameObject.AddComponent<TextMesh>();text.text=content;text.fontSize=64;text.characterSize=size;text.anchor=TextAnchor.MiddleCenter;text.alignment=TextAlignment.Center;text.color=colour;
        Font font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");text.font=font;t.GetComponent<MeshRenderer>().sharedMaterial=font.material;
    }
    void BuildSiteFixture(Transform parent,SiteFixture fixture)
    {
        Transform t=Group(fixture.name,parent);t.localPosition=new Vector3(fixture.x,0,fixture.z);t.localRotation=Quaternion.Euler(0,fixture.yaw,0);
        if(fixture.kind=="Sign")
        {
            Box(t,"Blue wayfinding post",new Vector3(0,.80f,0),new Vector3(.065f,1.6f,.065f),"Sign blue",colliders);
            Box(t,"Blue entrance sign",new Vector3(0,1.62f,0),new Vector3(fixture.width,.46f,fixture.depth),"Sign blue",colliders);
            OutdoorText(t,"Entrance direction","ACCESSIBLE\nENTRANCE",new Vector3(0,1.64f,fixture.depth/2+.006f),180,.029f,Color.white);
            return;
        }
        Box(t,"Bin cabinet",new Vector3(0,fixture.height/2,0),new Vector3(fixture.width,fixture.height,fixture.depth),"Bin grey",colliders);
        Box(t,"Overhanging lid",new Vector3(0,fixture.height+.015f,0),new Vector3(fixture.width+.06f,.045f,fixture.depth+.06f),"Outdoor steel",colliders);
        Box(t,"Front collection opening",new Vector3(0,fixture.height*.83f,fixture.depth/2+.008f),new Vector3(fixture.width*.58f,.16f,.015f),"Piano",false);
        OutdoorText(t,"Waste stream label",fixture.kind=="Recycle"?"RECYCLE":"TRASH",new Vector3(0,fixture.height*.56f,fixture.depth/2+.019f),180,.035f,Color.white);
    }
    void CheckGeneratedNorthForecourt(Transform generatedRoot)
    {
        if(!includeSite)return;
        NorthSite plan=Data().northSite;
        Transform court=generatedRoot.Find("Site/North forecourt");
        if(court==null||court.Find("Two fenced patio table sets").childCount!=2||
            court.Find("Forecourt round tables and benches").childCount!=4||
            court.Find("Backless benches along patio wall and railing").childCount!=5||
            court.Find("Backless benches at curved lawn edge").childCount!=3||
            court.Find("L-shaped patio fence - entrance side open").childCount!=2)
            throw new InvalidOperationException("The north forecourt seating is incomplete. The previous building was kept.");
        if(court.Find("Photo-reference entrance statue")==null)
            throw new InvalidOperationException("The entrance statue was not generated.");
        Transform patioTables=court.Find("Two fenced patio table sets");
        for(int table=0;table<patioTables.childCount;table++)for(int seat=1;seat<=4;seat++)
            if(patioTables.GetChild(table).Find("Curved metal bench "+seat)==null)
                throw new InvalidOperationException("A patio table is missing its curved bench seats.");
        CheckWallMountedIdentification(generatedRoot);
        Transform level=generatedRoot.Find("Floor 2");
        foreach(StairAccess route in plan.access)
            for(int k=0;k<route.xz.Length-2;k+=2)
            {
                Vector3 a=new Vector3(route.xz[k],0,route.xz[k+1]),b=new Vector3(route.xz[k+2],0,route.xz[k+3]);
                Vector3 right=Vector3.Cross(Vector3.up,(b-a).normalized);
                int count=Mathf.Max(1,Mathf.CeilToInt(Vector3.Distance(a,b)/.10f));
                for(int i=0;i<=count;i++)foreach(float side in new[]{-.5f,0,.5f})
                    CheckStairWalkPoint(generatedRoot,level,Vector3.Lerp(a,b,(float)i/count)+right*(route.width*side),route.name);
            }
    }
    static Transform Group(string name,Transform parent)
    {Transform t=new GameObject(name).transform;t.SetParent(parent,false);return t;}
    GameObject Box(Transform parent,string name,Vector3 position,Vector3 size,string material,bool solid)
    {
        GameObject go=GameObject.CreatePrimitive(PrimitiveType.Cube);go.name=name;go.transform.SetParent(parent,false);go.transform.localPosition=position;go.transform.localScale=size;go.GetComponent<Renderer>().sharedMaterial=materials[material];if(!solid)DestroyImmediate(go.GetComponent<Collider>());return go;
    }
    void Beam(Transform parent,Vector3 a,Vector3 b,float width)
    {Vector3 d=b-a;if(d.magnitude<.001f)return;GameObject go=Box(parent,"Red handrail",(a+b)/2,new Vector3(width,d.magnitude,width),"Rail",colliders);go.transform.localRotation=Quaternion.FromToRotation(Vector3.up,d.normalized);}
    static void Label(Transform parent,string text,Vector3 position)
    {
        Transform t=Group(text,parent);t.localPosition=position;t.localRotation=Quaternion.Euler(90,0,0);TextMesh label=t.gameObject.AddComponent<TextMesh>();label.text=text;label.fontSize=48;label.characterSize=.075f;label.anchor=TextAnchor.MiddleCenter;label.color=Color.black;
        Font font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");label.font=font;t.GetComponent<MeshRenderer>().sharedMaterial=font.material;
    }
    static void EnsureFolders()
    {if(!AssetDatabase.IsValidFolder(AssetRoot))AssetDatabase.CreateFolder("Assets","EngineeringBuildingGenerated");if(!AssetDatabase.IsValidFolder(Folder))AssetDatabase.CreateFolder(AssetRoot,"V69");}
    void EnsureMaterials()
    {
        materials.Clear();
        Mat("Statue bronze",new Color(.12f,.11f,.095f));Mat("Flower rose",new Color(.52f,.18f,.24f));Mat("Flower burgundy",new Color(.34f,.09f,.14f));
        Mat("Patio concrete",new Color(.61f,.62f,.60f));Mat("Outdoor steel",new Color(.13f,.16f,.16f));
        Mat("Lawn",new Color(.32f,.46f,.20f));Mat("Mulch",new Color(.22f,.17f,.12f));Mat("Hedge",new Color(.19f,.27f,.12f));
        Mat("Tree bark",new Color(.32f,.30f,.25f));Mat("Tree leaves light",new Color(.43f,.49f,.28f));Mat("Tree leaves dark",new Color(.30f,.38f,.21f));
        Mat("Umbrella canvas",new Color(.75f,.71f,.52f));Mat("Bin grey",new Color(.26f,.29f,.28f));Mat("Sign blue",new Color(.08f,.24f,.48f));
Mat("Wall",new Color(.85f,.86f,.86f));Mat("Corridor",new Color(.91f,.91f,.9f));
        Mat("Lecture",new Color(.8f,.6f,.8f));Mat("Imagination",new Color(1,.6f,0));Mat("Realization",new Color(1,1,0));
        Mat("Department",new Color(.6f,1,.4f));Mat("Office",new Color(.6f,1,1));Mat("Public",new Color(.96f,.588f,.596f));Mat("Operations",new Color(.875f,.835f,.839f));
        Mat("Stair",new Color(.22f,.23f,.24f));Mat("Nosing",new Color(.95f,.85f,.08f));Mat("Rail",new Color(.65f,.06f,.04f));Mat("Concrete",new Color(.63f,.64f,.63f));Mat("Terrain",new Color(.26f,.4f,.2f));
        Mat("Metal",new Color(.4f,.45f,.48f));Mat("Glass",new Color(.4f,.7f,.8f,.28f));Mat("Piano",new Color(.055f,.035f,.025f));Mat("Ivory",new Color(.97f,.95f,.88f));
        Mat("Facade panel",new Color(.74f,.70f,.65f));Mat("Facade white",new Color(.90f,.90f,.86f));
        Mat("Wing brick panel",new Color(.48f,.27f,.21f));Mat("Window silver",new Color(.52f,.57f,.58f));Mat("Window brown",new Color(.38f,.25f,.20f));
        Mat("Window glass",new Color(.26f,.36f,.40f,.58f));Mat("Shade detail",new Color(.70f,.72f,.69f));Mat("Panel joint",new Color(.62f,.59f,.55f));
        Mat("Roof concrete",new Color(.69f,.70f,.68f));Mat("Roof membrane",new Color(.50f,.53f,.52f));
        Mat("Roof coping",new Color(.78f,.80f,.78f));Mat("Roof shaded zone",new Color(.65f,.52f,.36f));
        Mat("Picnic concrete",new Color(.62f,.64f,.60f));Mat("Vending blue",new Color(.10f,.23f,.48f));Mat("Vending red",new Color(.62f,.11f,.10f));
        foreach(string name in new[]{"Glass","Window glass"})
        {
            Material glass=materials[name];if(glass.HasProperty("_Surface"))glass.SetFloat("_Surface",1);if(glass.HasProperty("_Mode"))glass.SetFloat("_Mode",3);
            if(glass.HasProperty("_SrcBlend"))glass.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);if(glass.HasProperty("_DstBlend"))glass.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);if(glass.HasProperty("_ZWrite"))glass.SetFloat("_ZWrite",0);
            if(glass.HasProperty("_Smoothness"))glass.SetFloat("_Smoothness",.6f);if(glass.HasProperty("_Glossiness"))glass.SetFloat("_Glossiness",.6f);
            glass.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");glass.EnableKeyword("_ALPHABLEND_ON");glass.SetOverrideTag("RenderType","Transparent");glass.renderQueue=3000;glass.SetShaderPassEnabled("ShadowCaster",false);EditorUtility.SetDirty(glass);
        }
    }
    void Mat(string name,Color color)
    {
        string path=Folder+"/"+name+".mat";Material m=AssetDatabase.LoadAssetAtPath<Material>(path);
        if(m==null){Shader shader=Shader.Find("Universal Render Pipeline/Lit")??Shader.Find("Standard");if(shader==null)throw new InvalidOperationException("URP/Lit or Standard shader required.");m=new Material(shader){name=name};m.color=color;if(m.HasProperty("_BaseColor"))m.SetColor("_BaseColor",color);AssetDatabase.CreateAsset(m,path);}materials[name]=m;
    }
    static GameObject FindBuilding()
    {
        Scene scene=SceneManager.GetActiveScene();
        return scene.IsValid()&&scene.isLoaded?scene.GetRootGameObjects().FirstOrDefault(g=>g.name==RootName):null;
    }
    static Transform FloorRoot(int n){GameObject root=FindBuilding();return root!=null?root.transform.Find("Floor "+n):null;}
    void DespawnFloor(int n)
    {
        if(IsPlaySession){status="Stop Play Mode before despawning floors.";Repaint();return;}
        Transform floor=FloorRoot(n);if(floor==null)return;
        GameObject root=FindBuilding();Transform connections=root!=null?root.transform.Find("Stair connections/From Floor "+n):null;
        Undo.IncrementCurrentGroup();int group=Undo.GetCurrentGroup();Undo.SetCurrentGroupName("Despawn Floor "+n);
        if(connections!=null)Undo.DestroyObjectImmediate(connections.gameObject);
        Undo.DestroyObjectImmediate(floor.gameObject);Undo.CollapseUndoOperations(group);
        SyncLabels();Dirty();status="Floor "+n+" despawned. Undo or regenerate to restore it.";
    }
    static void Render(Transform t,bool visible)
    {foreach(Renderer r in t.GetComponentsInChildren<Renderer>(true)){RecordSceneChange(r,"Floor renderers");r.enabled=visible;}Dirty();}
    void Preset(int n)
    {
        for(int i=1;i<=FloorCount;i++)
        {Transform t=FloorRoot(i);if(t==null)continue;RecordSceneChange(t.gameObject,"Inspect floors");t.gameObject.SetActive(n==0||i==n);Render(t,true);}
        GameObject root=FindBuilding();Transform connections=root!=null?root.transform.Find("Stair connections"):null;
        if(connections!=null){RecordSceneChange(connections.gameObject,"Inspect connections");connections.gameObject.SetActive(true);for(int i=1;i<=FloorCount;i++){Transform child=connections.Find("From Floor "+i);if(child==null)continue;RecordSceneChange(child.gameObject,"Inspect connection");child.gameObject.SetActive(n==0||i==n||i==n-1);}}
        Transform site=root!=null?root.transform.Find("Site"):null;if(site!=null){RecordSceneChange(site.gameObject,"Inspect site");site.gameObject.SetActive(n==0||n==2);}SyncLabels();Dirty();
        Transform roofs=root!=null?root.transform.Find("Roofs"):null;
        if(roofs!=null)
        {
            RecordSceneChange(roofs.gameObject,"Inspect roofs");roofs.gameObject.SetActive(roofsVisible);
            Roof[] definitions=runtimePlans!=null&&runtimePlans.roofs!=null?runtimePlans.roofs:new Roof[0];
            foreach(Roof roof in definitions)
            {
                Transform cap=roofs.Find(roof.name);if(cap==null)continue;
                RecordSceneChange(cap.gameObject,"Inspect roofs");cap.gameObject.SetActive(n==0||roof.aboveFloor==n-1);
                Render(cap,true);
            }
        }
        SyncLabels();Dirty();
    }
    void SyncLabels()
    {
        int highest=0;for(int i=1;i<=FloorCount;i++){Transform t=FloorRoot(i);if(t!=null&&t.gameObject.activeInHierarchy&&t.GetComponentsInChildren<MeshRenderer>(true).Any(r=>r.enabled&&r.GetComponent<TextMesh>()==null))highest=i;}
        for(int i=1;i<=FloorCount;i++){Transform t=FloorRoot(i);Transform labels=t!=null?t.Find("Room labels"):null;if(labels!=null&&labels.gameObject.activeSelf!=(roomLabels&&highest==i&&(t.Find("Reference overlay")==null||!t.Find("Reference overlay").gameObject.activeSelf)))labels.gameObject.SetActive(roomLabels&&highest==i&&(t.Find("Reference overlay")==null||!t.Find("Reference overlay").gameObject.activeSelf));}
    }
    static void Dirty()
    {
        // Visibility controls are also useful during Play Mode. Runtime scene
        // changes must not call the edit-only MarkSceneDirty API.
        if(!IsPlaySession)
        {
            Scene scene=SceneManager.GetActiveScene();
            if(scene.IsValid()&&scene.isLoaded)EditorSceneManager.MarkSceneDirty(scene);
        }
        SceneView.RepaintAll();
    }
